manifest:
[package]
name = "openpipestress-desktop"
version = "0.1.0"
description = "OpenPipeStress macOS technical preview desktop shell"
authors = ["OpenPipeStress contributors"]
edition = "2021"

[lib]
name = "openpipestress_desktop_lib"
crate-type = ["staticlib", "cdylib", "rlib"]

[build-dependencies]
tauri-build = { version = "2", features = [] }

[dependencies]
open_pipe_stress_product_physics = { path = "../../../core/product_physics" }
open_pipe_stress_self_weight_wasm = { path = "../../../core/loads/self_weight_wasm" }
open_pipe_stress_operation_applier = { path = "../../../core/model_operations/operation_applier" }
open_pipe_stress_library_import_document = { path = "../../../core/library_import/library_import_document" }
open_pipe_stress_report_renderer = { path = "../../../core/reporting/report_renderer" }
open_pipe_stress_report_package = { path = "../../../core/reporting/report_package" }
open_pipe_stress_audit_manifest = { path = "../../../core/reporting/audit_manifest" }
open_pipe_stress_result_export = { path = "../../../core/reporting/result_export" }
open_pipe_stress_rule_pack_document = { path = "../../../core/rules/rule_pack_document" }
open_pipe_stress_rule_check_runner = { path = "../../../core/rules/rule_check_runner" }
open_pipe_stress_units = { path = "../../../core/units" }
rusqlite = { version = "0.32", features = ["bundled"] }
serde = { version = "1", features = ["derive"] }
serde_json = "1"
getrandom = "0.3"
tauri = { version = "2", features = [] }
tauri-plugin-dialog = "2"

[package]
name = "open_pipe_stress_product_physics"
version = "0.1.0"
edition = "2021"
description = "Product-preview physics adapter for OpenPipeStress"
publish = false

[lib]
path = "src/lib.rs"

[dependencies]
open_pipe_stress_curved_bend = { path = "../solver/curved_bend" }
open_pipe_stress_frame_kernel = { path = "../solver/frame_kernel" }
open_pipe_stress_load_case_algebra = { path = "../loads/load_case_algebra" }
open_pipe_stress_linear_supports = { path = "../solver/linear_supports" }
open_pipe_stress_nonlinear_integration = { path = "../solver/nonlinear_integration" }
open_pipe_stress_nonlinear_supports = { path = "../solver/nonlinear_supports" }
open_pipe_stress_primitive_loads = { path = "../loads/primitive_loads" }
open_pipe_stress_solver_diagnostics = { path = "../solver/diagnostics" }
open_pipe_stress_sparse_direct = { path = "../solver/sparse_direct" }
open_pipe_stress_straight_pipe = { path = "../solver/straight_pipe" }
open_pipe_stress_stress_recovery = { path = "../loads/stress_recovery" }
open_pipe_stress_units = { path = "../units" }
serde = { version = "1", features = ["derive"] }
serde_json = "1"

[package]
name = "open_pipe_stress_report_package"
version = "0.1.0"
edition = "2021"
description = "Deterministic full-report-package container assembly for OpenPipeStress (DEC-028 / DEC-057 / DEC-061, completion-plan row E3)"
publish = false

[lib]
path = "src/lib.rs"

[dependencies]
open_pipe_stress_pdf_emitter = { path = "../pdf_emitter" }
open_pipe_stress_report_renderer = { path = "../report_renderer" }
open_pipe_stress_audit_manifest = { path = "../audit_manifest" }
open_pipe_stress_result_export = { path = "../result_export" }
open_pipe_stress_canonical_json = { path = "../../serialization/canonical_json" }
serde = { version = "1", features = ["derive"] }
serde_json = "1"
sha2 = "0.10"

[dev-dependencies]
open_pipe_stress_report_generator = { path = "../report_generator", features = ["serde"] }
open_pipe_stress_report_sections = { path = "../report_sections", features = ["serde"] }

[package]
name = "open_pipe_stress_rule_check_runner"
version = "0.1.0"
edition = "2021"
description = "End-to-end rule-check orchestration (C4): completeness, frozen-grammar formula decode and evaluation, ratio-vs-limit acceptability composition, per-check status, and worst-of aggregation over a rule-pack document plus caller-resolved solver and user values. No text parsing, no network/host/filesystem access, no protected content, no compliance claims."

[dependencies]
open_pipe_stress_expression_evaluator = { path = "../expression_evaluator" }
open_pipe_stress_completeness_checker = { path = "../completeness_checker" }
open_pipe_stress_rule_pack_document = { path = "../rule_pack_document" }
open_pipe_stress_units = { path = "../../units" }
serde = { version = "1", features = ["derive"] }
serde_json = "1"

[package]
name = "open_pipe_stress_rule_pack_document"
version = "0.1.0"
edition = "2021"
description = "Rule-pack document seam: production codec between the rule-pack JSON document encoding and the frozen DEC-022 expression AST, JCS checksum computation over pack documents, and document-level lifecycle validation. No text parsing of expressions, no protected content, no compliance claims."

[dependencies]
open_pipe_stress_expression_evaluator = { path = "../expression_evaluator" }
open_pipe_stress_rule_pack_lifecycle = { path = "../rule_pack_lifecycle" }
open_pipe_stress_canonical_json = { path = "../../serialization/canonical_json" }
serde = { version = "1", features = ["derive"] }
serde_json = "1"

[package]
name = "open_pipe_stress_solver_diagnostics"
version = "0.1.0"
edition = "2021"
description = "Code-neutral solver diagnostics for OpenPipeStress"
publish = false

[lib]
path = "src/lib.rs"

[dependencies]
open_pipe_stress_frame_kernel = { path = "../frame_kernel" }
open_pipe_stress_linear_supports = { path = "../linear_supports" }
open_pipe_stress_primitive_loads = { path = "../../loads/primitive_loads" }
open_pipe_stress_sparse_direct = { path = "../sparse_direct" }

[package]
name = "open_pipe_stress_nonlinear_integration"
version = "0.1.0"
edition = "2021"
description = "Assembled nonlinear active-set integration loop for OpenPipeStress"
publish = false

[lib]
path = "src/lib.rs"

[dependencies]
open_pipe_stress_curved_bend = { path = "../curved_bend" }
open_pipe_stress_frame_kernel = { path = "../frame_kernel" }
open_pipe_stress_nonlinear_supports = { path = "../nonlinear_supports" }
open_pipe_stress_solver_diagnostics = { path = "../diagnostics" }
open_pipe_stress_sparse_direct = { path = "../sparse_direct" }

[package]
name = "open_pipe_stress_mechanics_benchmarks"
version = "0.1.0"
edition = "2021"
description = "Original mechanics verification benchmarks for OpenPipeStress"
publish = false

[lib]
path = "src/lib.rs"

[dependencies]
open_pipe_stress_curved_bend = { path = "../../../core/solver/curved_bend" }
open_pipe_stress_frame_kernel = { path = "../../../core/solver/frame_kernel" }
open_pipe_stress_linear_supports = { path = "../../../core/solver/linear_supports" }
open_pipe_stress_primitive_loads = { path = "../../../core/loads/primitive_loads" }
open_pipe_stress_result_export = { path = "../../../core/reporting/result_export" }
open_pipe_stress_solver_diagnostics = { path = "../../../core/solver/diagnostics" }
open_pipe_stress_straight_pipe = { path = "../../../core/solver/straight_pipe" }
open_pipe_stress_user_loads = { path = "../../../core/loads/user_loads" }
serde_json = "1"
sha2 = "0.10"

[package]
name = "open_pipe_stress_nonlinear_benchmarks"
version = "0.1.0"
edition = "2021"
description = "Original nonlinear support regression benchmarks for OpenPipeStress"
publish = false

[lib]
path = "src/lib.rs"

[dependencies]
open_pipe_stress_frame_kernel = { path = "../../../core/solver/frame_kernel" }
open_pipe_stress_nonlinear_integration = { path = "../../../core/solver/nonlinear_integration" }
open_pipe_stress_nonlinear_supports = { path = "../../../core/solver/nonlinear_supports" }
open_pipe_stress_solver_diagnostics = { path = "../../../core/solver/diagnostics" }
